# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KIRTASİYEDE (فِي الْمَكْتَبَةِ) TEMEL MALZEMELER VE İFADELER</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Okul ve Kırtasiye Araçları</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• دَفْتَرٌ (Defterun): Defter</text>\n  <text x="40" y="122" font-size="11.5" fill="#334155">• قَلَمٌ (Kalemun): Kalem</text>\n  <text x="40" y="146" font-size="11.5" fill="#334155">• مِسْطَرَةٌ (Mistaratun): Cetvel</text>\n  <text x="40" y="170" font-size="11.5" fill="#334155">• مِمْحَاةٌ (Mimhâtun): Silgi</text>\n  <text x="40" y="194" font-size="11.5" fill="#334155">• مِبْرَاةٌ (Mibrâtun): Kalemtıraş</text>\n  <text x="40" y="218" font-size="11.5" fill="#334155">• حَقِيبَةٌ (Hakîbetun): Çanta</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İhtiyaç ve İstek Kalıpları</text>\n  <text x="260" y="100" font-size="11.5" font-weight="bold" fill="#166534">أَنَا بِحَاجَةٍ إِلَى...</text>\n  <text x="260" y="118" font-size="11" fill="#334155">(Enâ bi-hâcetin ilâ... = ...ihtiyacım var)</text>\n  <text x="260" y="146" font-size="11.5" font-weight="bold" fill="#166534">أُرِيدُ قَلَمًا وَدَفْتَرًا</text>\n  <text x="260" y="164" font-size="11" fill="#334155">(Ürîdü kalemen ve defteran = Kalem ve</text>\n  <text x="260" y="180" font-size="11" fill="#334155">defter istiyorum)</text>\n  <text x="260" y="208" font-size="11.5" font-weight="bold" fill="#166534">هَلْ عِنْدَكَ مِقَصٌّ؟</text>\n  <text x="260" y="224" font-size="11" fill="#334155">(Hel indeke mikassun? = Makas var mı?)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Nezaket ve Satış İfadeleri</text>\n  <text x="480" y="100" font-size="11.5" fill="#334155">• مَرْحَبًا، أَيَّ خِدْمَةٍ؟ (Nasıl yardımcı...)</text>\n  <text x="480" y="125" font-size="11.5" fill="#334155">• لَوْ سَمَحْتَ / مِنْ فَضْلِكَ (Lütfen)</text>\n  <text x="480" y="150" font-size="11.5" fill="#334155">• تَفَضَّلْ / تَفَضَّلِي (Buyur / Buyurun)</text>\n  <text x="480" y="175" font-size="11.5" fill="#334155">• هَلْ تُرِيدُ شَيْئًا آخَرَ؟ (Başka bir şey?)</text>\n  <text x="480" y="200" font-size="11.5" fill="#334155">• شُكْرًا جَزِيلًا — عَفْوًا (Teşekkür / Rica)</text>\n  <text x="570" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">الْبَائِعُ (Satıcı) — الْمُشْتَرِي (Müşteri)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİYAT SORMA (بِكَمْ؟) VE BAĞLAÇLARLA TERCİH BİLDİRME</text>\n  <rect x="30" y="50" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Müzekker ve Müennes İsimlerde Fiyat Sorma</text>\n  <text x="48" y="104" font-size="12" font-weight="bold" fill="#1e40af">1. Müzekker (Eril) Eşyalar İçin:</text>\n  <text x="48" y="126" font-size="11.5" fill="#334155">بِكَمْ هٰذَا الدَّفْتَرُ؟ (Bikem hâze\'d-defteru?)</text>\n  <text x="48" y="144" font-size="11" fill="#475569">→ هٰذَا الدَّفْتَرُ بِعَشْرِ لِيرَاتٍ. (Bu defter 10 liradır.)</text>\n  <text x="48" y="174" font-size="12" font-weight="bold" fill="#1e40af">2. Müennes (Dişil - ة) Eşyalar İçin:</text>\n  <text x="48" y="196" font-size="11.5" fill="#334155">بِكَمْ هٰذِهِ الْحَقِيبَةُ؟ (Bikem hâzihi\'l-hakîbetü?)</text>\n  <text x="48" y="214" font-size="11" fill="#475569">→ هٰذِهِ الْحَقِيبَةُ بِعِشْرِينَ لِيرَةً. (Bu çanta 20 liradır.)</text>\n  <rect x="365" y="50" width="305" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Seçim Soruları ve Bağlaçlar (و، أَوْ، أَمْ، ثُمَّ)</text>\n  <text x="383" y="104" font-size="11.5" fill="#334155">• وَ (ve): İki ürünü birlikte isteme (قَلَمٌ وَدَفْتَرٌ)</text>\n  <text x="383" y="130" font-size="11.5" fill="#334155">• أَمْ (em): Soru cümlesinde &quot;yoksa&quot; anlamı</text>\n  <text x="395" y="148" font-size="11" font-weight="bold" fill="#991b1b">أَتُفَضِّلُ الْقَلَمَ الْأَزْرَقَ أَمِ الْأَحْمَرَ؟</text>\n  <text x="395" y="165" font-size="10.5" fill="#475569">(Mavi kalemi mi yoksa kırmızı kalemi mi tercih edersin?)</text>\n  <text x="383" y="190" font-size="11.5" fill="#334155">• أَوْ (ev): Düz cümlede &quot;veya&quot; seçeneği</text>\n  <text x="383" y="214" font-size="11.5" fill="#334155">• ثُمَّ (sümme): Sıralama (&quot;sonra&quot;) bağlacı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SAYILARLA (11-19) ALIŞVERİŞ VE TİCARET AHLAKI İLKELERİ</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kırtasiye Alışverişinde Sayılar (10-19)</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• 10: عَشَرَةُ أَقْلَامٍ (Aşaratu eklâmin - 10 kalem)</text>\n  <text x="48" y="126" font-size="11.5" fill="#334155">• 11: أَحَدَ عَشَرَ دَفْتَرًا (Ehade aşara defteran)</text>\n  <text x="48" y="150" font-size="11.5" fill="#334155">• 12: اِثْنَتَا عَشْرَةَ مِمْحَاةً (İsnetâ aşrate mimhâten)</text>\n  <text x="48" y="174" font-size="11.5" fill="#334155">• 15: خَمْسَ عَشْرَةَ لِيرَةً (Hamse aşrate lîraten - 15 TL)</text>\n  <text x="185" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">المَجْمُوعُ (el-Mecmûu): Toplam Tutar</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ticaret Ahlakı ve Dürüstlük Mesajları</text>\n  <text x="378" y="104" font-size="11.5" font-weight="bold" fill="#92400e">• اِنْتَبِهْ لِلْكَيْلِ وَالْمِيزَانِ</text>\n  <text x="388" y="122" font-size="11" fill="#334155">(Ölçüye ve tartıya dikkat et!)</text>\n  <text x="378" y="150" font-size="11.5" font-weight="bold" fill="#92400e">• اللّٰهُ لَا يُحِبُّ الْمُطَفِّفِينَ</text>\n  <text x="388" y="168" font-size="11" fill="#334155">(Allah ölçü ve tartıda hile yapanları sevmez.)</text>\n  <text x="378" y="196" font-size="11.5" font-weight="bold" fill="#92400e">• الْكَاسِبُ حَبِيبُ اللّٰهِ</text>\n  <text x="388" y="214" font-size="11" fill="#334155">(Helalinden çalışan/kazanan Allah\'ın dostudur.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
